?><div class="jp-admin-results"><p role="status"><?= $list['total'] ?> matching employers</p><a class="jp-text-link" href="/pages/admin-companies.php">Clear filters</a></div><?php if(!$list['rows']):jobproAdminEmpty('No matching companies.','Try another company name or address.','/pages/admin-companies.php','Clear search');else: ?><div class="jp-admin-card-grid"><?php foreach($list['rows']as$row): ?><article class="jp-admin-record-card"><div class="jp-admin-section-heading"><span class="jp-admin-record-mark" aria-hidden="true"><?= jobproEscape(mb_strtoupper(mb_substr($row['company_name']?:'JP',0,2))) ?></span><?php jobproAdminBadge($row['account_status']); ?></div><h2><?= jobproEscape($row['company_name']?:'Company profile') ?></h2><p class="jp-admin-muted"><?= jobproEscape($row['address']?:'Address not provided') ?></p><p class="jp-admin-muted"><?= (int)$row['job_count'] ?> posted jobs</p><div class="jp-admin-actions"><a class="jp-text-link" href="/pages/admin-jobs.php?company=<?= (int)$row['company_id'] ?>">Review jobs →</a><?php if($adminRole==='owner'): ?><a class="jp-text-link" href="/pages/admin-user.php?id=<?= (int)$row['user_id'] ?>">Manage account →</a><?php endif; ?><a class="jp-text-link" href="/pages/company.php?id=<?= (int)$row['company_id'] ?>">Public profile ↗</a></div></article><?php endforeach; ?></div><?php jobproAdminPager($list,'/pages/admin-companies.php',$f);endif;
